const CACHE='generation-z-v0.2.2-profile';
const ASSETS=["./data/profile.js", "./systems/profile.js", "./ui/profile.js", "./ui/profile.css", "./", "./assets/character-blue.webp", "./assets/character-mint.webp", "./assets/favicon.svg", "./assets/live-room-0.webp", "./assets/live-room-1.webp", "./assets/live-room-2.webp", "./assets/room-0.webp", "./assets/room-1.webp", "./assets/room-2.webp", "./assets/room-props.webp", "./core/game.js", "./core/save.js", "./data/config.js", "./data/events.js", "./data/offers.js", "./index.html", "./locales/index.js", "./services/platform.js", "./systems/events.js", "./systems/goals.js", "./systems/monetization.js", "./ui/app.js", "./ui/icons.js", "./ui/motion.js", "./ui/offers.js", "./ui/polish.css", "./ui/theme.css", "./ui/scene.js", "./ui/screens.js", "./ui/style.css"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('generation-z-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;
const url=new URL(event.request.url);const known=ASSETS.some(asset=>new URL(asset,self.registration.scope).pathname===url.pathname);if(!known)return;
event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy)).catch(()=>{});}return response;}).catch(async()=>{const cached=await caches.match(event.request,{ignoreSearch:true});if(cached)return cached;if(event.request.mode==='navigate')return caches.match(new URL('./index.html',self.registration.scope).href);return Response.error();}));});
